        studies: [{year:2022, finding:"Reduced gut permeability & improved immunity in athletes (meta)", source:"Nutrients"}, {year:2023, finding:"Faster recovery from exercise & reduced URI incidence", source:"J Int Soc Sports Nutr"}, {year:2024, finding:"Improved lean mass & gut markers in older adults", source:"J Gerontol"}],
        dosage: "1–3 g daily (or 10-20g for gut repair protocols; start low)", synergies: ["probiotic", "prebiotic", "glutamine (not listed)", "omega3"],
